def proxy_profiling_service(
    method: str,
    path: str,
    params: Optional[Dict[str, Any]] = None,
    headers: Optional[Dict[str, str]] = None,
) -> HttpResponse:
    profiling_response = get_from_profiling_service(method, path, params=params, headers=headers)
    return HttpResponse(
        content=profiling_response.data,
        status=profiling_response.status,
        content_type=profiling_response.headers.get("Content-Type", "application/json"),
    )

@metrics.wraps("process_profile.insert_vroom_profile")
def _insert_vroom_profile(profile: Profile) -> bool:
    original_timestamp = profile["received"]

    try:
        profile["received"] = (
            datetime.utcfromtimestamp(profile["received"]).replace(tzinfo=timezone.utc).isoformat()
        )
        response = get_from_profiling_service(method="POST", path="/profile", json_data=profile)

        if response.status == 204:
            profile["call_trees"] = {}
        elif response.status == 200:
            profile["call_trees"] = json.loads(response.data)["call_trees"]
        else:
            metrics.incr(
                "profiling.insert_vroom_profile.error",
                tags={"platform": profile["platform"], "reason": "bad status"},
            )
            return False
        return True
    except RecursionError as e:
        sentry_sdk.set_context(
            "profile",
            {
                "organization_id": profile["organization_id"],
                "project_id": profile["project_id"],
                "profile_id": profile["event_id"]
                if "event_id" in profile
                else profile["profile_id"],
                "platform": profile["platform"],
            },
        )
        sentry_sdk.capture_exception(e)
        return True
    except Exception as e:
        sentry_sdk.capture_exception(e)
        metrics.incr(
            "profiling.insert_vroom_profile.error",
            tags={"platform": profile["platform"], "reason": "encountered error"},
        )
        return False
    finally:
        profile["received"] = original_timestamp

        # remove keys we don't need anymore for snuba
        for k in {"profile", "debug_meta"}:
            profile.pop(k, None)

def get_data_fn(
    self, request: Request, organization: Organization, kwargs: Dict[str, Any]
) -> Any:
    def data_fn(offset: int, limit: int) -> Any:
        sort = request.query_params.get("sort", None)
        if sort is None:
            raise ParseError(detail="Invalid query: Missing value for sort")
        kwargs["params"]["sort"] = sort

        kwargs["params"]["offset"] = offset
        kwargs["params"]["limit"] = limit

        response = get_from_profiling_service(
            "GET",
            f"/organizations/{organization.id}/transactions",
            **kwargs,
        )
        data = json.loads(response.data)

        return data.get("transactions", [])

    return data_fn

